def main(root):
    for lang, values in L.items():
        assert len(values) == len(KEYS), (lang, len(values), len(KEYS))
        d = os.path.join(root, "_locales", lang)
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "messages.json"), "w", encoding="utf-8") as f:
            json.dump({k: {"message": v} for k, v in zip(KEYS, values)}, f, ensure_ascii=False, indent=2)
            f.write("\n")
    print(len(L), "locales,", len(KEYS), "messages each")

if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else ".")
